import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md","lastUpdated":null}'),n={name:"guide/intro.md"};function i(l,t,d,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h1><blockquote><p>⚠️ <strong>免责声明</strong> 本项目是<strong>非官方</strong>接口文档，与网易（NetEase）及其关联公司<strong>无任何关联</strong>，未经网易官方授权。 本文档内容基于公开前端资源的逆向整理，<strong>仅供学习研究</strong>，请勿用于任何商业用途或恶意行为。 使用本接口产生的一切后果由使用者自行承担。如侵犯您的权益，请联系删除。</p></blockquote><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>网易我的世界开发者平台（MCDev，<code>mcdev.webapp.163.com</code>）是《我的世界》中国版开发者的内容管理后台， 提供作品上传、审核、上架、收益结算等功能。本仓库整理其<strong>前端 Web API 接口</strong>，方便开发者：</p><ul><li>通过代码自动化管理自己的作品（上传 / 自测 / 审核 / 上架 / 删除）</li><li>查询收益、数据分析、站内信、活动等</li><li>作为第三方工具（如移动端 App）的接口参考</li></ul><h2 id="信息来源" tabindex="-1">信息来源 <a class="header-anchor" href="#信息来源" aria-label="Permalink to &quot;信息来源&quot;">​</a></h2><p>本文档的接口信息来自两个途径：</p><table tabindex="0"><thead><tr><th>来源</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://github.com/BitterLemonn/MCDevManager" target="_blank" rel="noreferrer">BitterLemonn/MCDevManager</a></td><td>Kotlin Multiplatform 第三方管理工具，实现了大部分接口</td></tr><tr><td>官方网页版前端 JS</td><td><code>mcdev.webapp.163.com</code> 的 <code>app.js</code> 与按需加载 chunk，<strong>补充了官方网页版的删除作品 / 自测 / 取消自测 / 商品管理等接口</strong></td></tr></tbody></table><h2 id="接口特点" tabindex="-1">接口特点 <a class="header-anchor" href="#接口特点" aria-label="Permalink to &quot;接口特点&quot;">​</a></h2><ul><li><strong>Base URL</strong>：<code>https://mc-launcher.webapp.163.com/</code></li><li><strong>响应格式</strong>：统一 <code>{ status, data, msg }</code> 结构</li><li><strong>认证方式</strong>：Cookie 会话（登录后由服务端下发）</li><li><strong>登录加密</strong>：RSA PKCS1（公钥加密，非对称）</li></ul><h2 id="相关项目" tabindex="-1">相关项目 <a class="header-anchor" href="#相关项目" aria-label="Permalink to &quot;相关项目&quot;">​</a></h2><ul><li><a href="https://github.com/xtt-xt/Nemo-Mobile-Mod-Studio" target="_blank" rel="noreferrer">Nemo-Mobile-Mod-Studio</a>：网易基岩版 Minecraft 可视化模组制作工具（Android）</li><li><a href="https://github.com/xtt-xt/ore-ui-for-android" target="_blank" rel="noreferrer">ore-ui-for-android</a>：Android UI 控件库</li></ul>',12)])])}const p=e(n,[["render",i]]);export{g as __pageData,p as default};
